:root {
  color-scheme: light dark;
  --texte: light-dark(#1b1f24, #eceff3);
  --fond:  light-dark(#ffffff, #14171b);
}
/* repli : couleurs simples, remplacées si la fonction est comprise */
body { color: #1b1f24; background-color: #ffffff; }
@supports (color: light-dark(black, white)) {
  body { color: var(--texte); background-color: var(--fond); }
}
